import{_ as r,o as a,c as o,a7 as e}from"./chunks/framework.Bn19FVGY.js";const s="/ruidu-docs/images/orbitcontrol/user-guide/flows-page-list.png",i="/ruidu-docs/images/orbitcontrol/user-guide/flows-form-new.gif",n="/ruidu-docs/images/orbitcontrol/user-guide/flows-page-logs.png",m=JSON.parse('{"title":"自动化流程","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/flows.md","filePath":"orbitcontrol/user-guide/flows.md"}'),d={name:"orbitcontrol/user-guide/flows.md"};function l(c,t,h,p,g,u){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="自动化流程" tabindex="-1">自动化流程 <a class="header-anchor" href="#自动化流程" aria-label="Permalink to &quot;自动化流程&quot;">​</a></h1><p>「自动化流程」让平台在特定事件发生时<strong>自动响应</strong>：定义触发条件（警报/告警）和响应动作（前往现场/执行任务），无需人工值守。典型场景：周界入侵自动响应——设备自动前往警报位置巡查。</p><h2 id="流程列表" tabindex="-1">流程列表 <a class="header-anchor" href="#流程列表" aria-label="Permalink to &quot;流程列表&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><p>列表展示所有流程，支持按名称或描述搜索，点击进入编辑。</p><h2 id="新建流程" tabindex="-1">新建流程 <a class="header-anchor" href="#新建流程" aria-label="Permalink to &quot;新建流程&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>流程由三部分组成：<strong>触发</strong>、<strong>条件</strong>、<strong>动作</strong>。</p><h3 id="第一步-选择触发类型" tabindex="-1">第一步：选择触发类型 <a class="header-anchor" href="#第一步-选择触发类型" aria-label="Permalink to &quot;第一步：选择触发类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>触发类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>安防警报</strong></td><td>场所级警报触发（来自警报系统），如消防占道、门禁异常、人员倒地</td></tr><tr><td><strong>设备告警</strong></td><td>设备自身告警触发，如低电量、信号丢失、GPS 信号丢失、突破地理围栏</td></tr></tbody></table><ul><li>安防警报可进一步<strong>过滤警报类型</strong>（多选，满足任一即触发；不选则不限类型）</li><li>设备告警需选择具体的<strong>告警类型</strong></li></ul><h3 id="第二步-选择站点与设备" tabindex="-1">第二步：选择站点与设备 <a class="header-anchor" href="#第二步-选择站点与设备" aria-label="Permalink to &quot;第二步：选择站点与设备&quot;">​</a></h3><p>先选站点，再选执行响应的设备。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>「设备告警」触发的流程<strong>无需选择执行设备</strong>：产生告警的设备自动执行响应任务。</p></div><h3 id="第三步-配置动作" tabindex="-1">第三步：配置动作 <a class="header-anchor" href="#第三步-配置动作" aria-label="Permalink to &quot;第三步：配置动作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>说明</th></tr></thead><tbody><tr><td><strong>前往警报位置</strong></td><td>设备自动导航到警报发生的地理位置，可设置到达后的巡逻半径（留空则不限）</td></tr><tr><td><strong>执行任务</strong></td><td>设备自动执行指定任务，从站点任务列表中选择</td></tr></tbody></table><p>每个流程带 60 秒冷却时间：冷却期内同一流程不会重复触发。</p><h2 id="执行日志" tabindex="-1">执行日志 <a class="header-anchor" href="#执行日志" aria-label="Permalink to &quot;执行日志&quot;">​</a></h2><p>流程每次触发都会记录执行日志。在流程列表进入流程详情，查看「执行日志」：</p><p><img src="'+n+'" alt="" class="w-1/2"></p><p>日志展示每次触发的时间、触发详情和执行结果。</p>',21)])])}const _=r(d,[["render",l]]);export{m as __pageData,_ as default};
